{
  "items": [
    {
      "name": "Polynomial.isIntegral_coeff_of_factors",
      "module_name": "Mathlib.RingTheory.Polynomial.IsIntegral",
      "kind": "theorem",
      "type": "∀ {R : Type u_1} {S : Type u_2} [inst : CommRing R] [inst_1 : CommRing S] [inst_2 : Algebra R S] (p : Polynomial S),\n  IsIntegral R p.leadingCoeff →\n    p.Splits → (∀ (x : S), p.IsRoot x → IsIntegral R x) → ∀ (i : ℕ), IsIntegral R (p.coeff i)"
    },
    {
      "name": "Polynomial.isIntegral_coeff_prod",
      "module_name": "Mathlib.RingTheory.Polynomial.IsIntegral",
      "kind": "theorem",
      "type": "∀ {R : Type u_1} {S : Type u_2} {ι : Type u_3} [inst : CommRing R] [inst_1 : CommRing S] [inst_2 : Algebra R S]\n  (s : Finset ι) (p : ι → Polynomial S),\n  (∀ i ∈ s, ∀ (j : ℕ), IsIntegral R ((p i).coeff j)) → ∀ (j : ℕ), IsIntegral R ((s.prod p).coeff j)"
    },
    {
      "name": "IsIntegral.coeff_of_isFractionRing",
      "module_name": "Mathlib.RingTheory.Polynomial.IsIntegral",
      "kind": "theorem",
      "type": "∀ {R : Type u_1} {S : Type u_2} [inst : CommRing R] [inst_1 : CommRing S] [inst_2 : Algebra R S] {p : Polynomial S},\n  IsIntegral (Polynomial R) p → ∀ (i : ℕ), IsIntegral R (p.coeff i)"
    },
    {
      "name": "Polynomial.coeff_le_of_roots_le",
      "module_name": "Mathlib.Topology.Algebra.Polynomial",
      "kind": "theorem",
      "type": "∀ {F : Type u_3} {K : Type u_4} [inst : CommRing F] [inst_1 : NormedField K] {p : Polynomial F} {f : F →+* K} {B : ℝ}\n  (i : ℕ),\n  p.Monic →\n    (Polynomial.map f p).Splits →\n      (∀ z ∈ (Polynomial.map f p).roots, ‖z‖ ≤ B) →\n        ‖(Polynomial.map f p).coeff i‖ ≤ B ^ (p.natDegree - i) * ↑(p.natDegree.choose i)"
    },
    {
      "name": "Polynomial.coeff_bdd_of_roots_le",
      "module_name": "Mathlib.Topology.Algebra.Polynomial",
      "kind": "theorem",
      "type": "∀ {F : Type u_3} {K : Type u_4} [inst : CommRing F] [inst_1 : NormedField K] {B : ℝ} {d : ℕ} (f : F →+* K)\n  {p : Polynomial F},\n  p.Monic →\n    (Polynomial.map f p).Splits →\n      p.natDegree ≤ d →\n        (∀ z ∈ (Polynomial.map f p).roots, ‖z‖ ≤ B) →\n          ∀ (i : ℕ), ‖(Polynomial.map f p).coeff i‖ ≤ max B 1 ^ d * ↑(d.choose (d / 2))"
    }
  ]
}
